// Author: MiYu. Cross-API placement, population, worker and shared mine consumers; execute with the gameplay stage batch.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_construction_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto real=[](float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));};auto number=[](jass::Real v){return std::bit_cast<float>(v.bits());};auto check=[](bool condition,const char* message){if(!condition)throw std::runtime_error(message);};auto code=[&](const char* type){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(type)));};auto& terrain=session.world()->data().terrain;float originX=terrain.origin[0]+1024,originY=terrain.origin[1]+1024;auto spawn=[&](const char* type,unsigned owner,float x,float y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),code(type),vm.real(real(x)),vm.real(real(y)),vm.real(real(270))});};auto position=[&](jass::Value unit,float x,float y){vm.invoke("SetUnitPosition",std::array{unit,vm.real(real(x)),vm.real(real(y))});};
        for(int field:{1,2,4,6})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(field<4?100000:1000)});
        unsigned nativeBuildOrders=0;auto place=[&](jass::Value worker,const char* name,bool blight=false){auto type=ObjectData::code(name);std::optional<WorldPoint> point;std::string reason;for(unsigned y=8;y+8<(terrain.height-1)*4 && !point;y+=4)for(unsigned x=8;x+8<(terrain.width-1)*4 && !point;x+=4){WorldPoint candidate{real(terrain.origin[0]+x*32),real(terrain.origin[1]+y*32)};if(blight)session.world()->blight(candidate,384,true);point=session.buildSite(worker.bits,type,candidate,reason);}check(point.has_value(),"No valid construction location in source map");auto size=session.buildingSize(type);position(worker,number(point->x)-size[0]/2-24,number(point->y));if(nativeBuildOrders++%2==0)check(vm.invoke("IssueBuildOrder",std::array{worker,vm.string(name),vm.real(point->x),vm.real(point->y)}).bits,"String build order rejected");else check(vm.invoke("IssueBuildOrderById",std::array{worker,code(name),vm.real(point->x),vm.real(point->y)}).bits,"ID build order rejected");session.advance(1./32);auto id=vm.global("probe_structure").bits;check(session.units().contains(id) && session.units().at(id)->type==type && session.units().at(id)->construction.has_value(),"Construction start did not create live structure/context");return vm.handle("unit",id);};
        auto peasant=spawn("hpea",0,originX,originY);auto menu=session.commands(peasant.bits,0,true);check(std::any_of(menu.begin(),menu.end(),[](auto& b){return b.action==CommandAction::Build && b.type==ObjectData::code("hhou");}),"Source build menu omitted farm");int capacity=session.config().players[0].states.at(4);auto farm=place(peasant,"hhou");auto farmState=session.units().at(farm.bits);WorldPoint center{farmState->x,farmState->y};check(!farmState->foodCounted && session.config().players[0].states.at(4)==capacity && (session.world()->pathMask(center)&8),"Unfinished building population or footprint differs");check(session.commands(farm.bits,0).empty(),"Unfinished building exposed active commerce");int paid=session.config().players[0].states.at(1);check(session.cancelConstruction(farm.bits),"Construction cancel rejected");check(!session.units().contains(farm.bits) && session.config().players[0].states.at(1)>paid && vm.global("probe_cancelled").bits==1 && !session.units().at(peasant.bits)->workingOn,"Cancellation did not refund, release worker and dispatch context");check(!(session.world()->pathMask(center)&8),"Cancelled building retained footprint");
        farm=place(peasant,"hhou");session.stopUnit(peasant.bits);auto halted=session.units().at(farm.bits)->construction->elapsed;session.advance(.125);check(session.units().at(farm.bits)->construction->elapsed==halted,"Stopped worker continued construction");check(session.targetOrder(peasant.bits,farm.bits,852024),"Resume construction rejected");vm.invoke("UnitSetConstructionProgress",std::array{farm,vm.integer(100)});check(!session.units().at(farm.bits)->construction && session.units().at(farm.bits)->foodCounted && vm.global("probe_finished").bits==1,"Completion did not activate population/context");auto barracks=place(peasant,"hbar");check(!session.train(barracks.bits,ObjectData::code("hfoo")),"Unfinished barracks accepted training");vm.invoke("KillUnit",std::array{barracks});check(!session.units().at(peasant.bits)->workingOn && !session.units().at(barracks.bits)->construction,"Building death retained builder/construction");
        auto peon=spawn("opeo",0,originX,originY);auto burrow=place(peon,"obur");check(session.units().at(peon.bits)->hidden(),"Orc builder did not enter construction");check(session.cancelConstruction(burrow.bits) && !session.units().at(peon.bits)->hidden(),"Orc cancellation retained hidden builder");auto wisp=spawn("ewsp",0,originX,originY);auto ancient=place(wisp,"eaom");vm.invoke("UnitSetConstructionProgress",std::array{ancient,vm.integer(100)});check(!session.units().contains(wisp.bits),"Ancient completion did not consume wisp");auto acolyte=spawn("uaco",0,originX,originY);auto ziggurat=place(acolyte,"uzig",true);check(!session.units().at(acolyte.bits)->workingOn && !session.units().at(acolyte.bits)->hidden(),"Undead summon retained builder");vm.invoke("UnitSetConstructionProgress",std::array{ziggurat,vm.integer(100)});
        auto mine=spawn("ngol",15,originX+1024,originY);auto tree=spawn("etol",0,originX+1024,originY+512);check(session.entangleMine(tree.bits,mine.bits,true),"Source instant entangle rejected");auto coverId=session.units().at(mine.bits)->mineCover;check(coverId && session.units().at(mine.bits)->hidden(),"Entangle did not cover underlying mine");auto cover=vm.handle("unit",coverId);vm.invoke("SetResourceAmount",std::array{cover,vm.integer(1234)});check(session.remainingResources(mine.bits)==1234 && session.remainingResources(coverId)==1234,"Mine stores diverged");vm.invoke("RemoveUnit",std::array{cover});check(!session.units().at(mine.bits)->hidden() && !session.units().at(tree.bits)->mineChild,"Mine removal retained cover/parent relationship");auto haunted=vm.invoke("CreateBlightedGoldmine",std::array{vm.handle("player",0x100000),vm.real(real(originX+2048)),vm.real(real(originY)),vm.real(real(270))});check(session.units().at(haunted.bits)->mineSource && session.remainingResources(haunted.bits)>0,"Blighted mine native omitted source store");check(vm.invoke("IssuePointOrder",std::array{peasant,vm.string("move"),vm.real(real(originX)),vm.real(real(originY))}).bits!=0,"String move order was misclassified as rawcode");
        auto town=spawn("htow",0,originX+3072,originY);vm.invoke("SetUnitUserData",std::array{town,vm.integer(123)});int beforeUpgrade=session.config().players[0].states.at(1);auto upgrades=session.commands(town.bits,0);check(std::any_of(upgrades.begin(),upgrades.end(),[](auto& b){return b.action==CommandAction::Upgrade && b.type==ObjectData::code("hkee") && b.gold==320 && b.lumber==210;}),"Upgrade menu did not subtract source cumulative prices");check(session.upgradeBuilding(town.bits,ObjectData::code("hkee")) && !session.train(town.bits,ObjectData::code("hpea")),"Upgrade did not block training");check(session.config().players[0].states.at(1)==beforeUpgrade-320 && vm.global("probe_upgrade_started").bits==1,"Upgrade fee/start event differs");check(session.cancelBuildingUpgrade(town.bits) && session.units().at(town.bits)->type==ObjectData::code("htow") && session.config().players[0].states.at(1)==beforeUpgrade-80 && vm.global("probe_upgrade_cancelled").bits==1,"Upgrade cancellation did not preserve source unit and refund");check(session.upgradeBuilding(town.bits,ObjectData::code("hkee")),"Second upgrade rejected");vm.invoke("UnitSetUpgradeProgress",std::array{town,vm.integer(100)});check(session.units().at(town.bits)->type==ObjectData::code("hkee") && session.units().at(town.bits)->userData==123 && number(session.units().at(town.bits)->maxLife)==2000 && vm.global("probe_upgrade_finished").bits==1,"Completed upgrade lost handle/state/stats/event");spawn("halt",0,originX+3072,originY+512);check(session.upgradeBuilding(town.bits,ObjectData::code("hcas")),"Castle prerequisites or upgrade failed");vm.invoke("UnitSetUpgradeProgress",std::array{town,vm.integer(-1)});check(session.units().at(town.bits)->type==ObjectData::code("hcas"),"Unsigned upgrade progress clamp differs");auto builds=session.commands(peasant.bits,0,true);check(std::any_of(builds.begin(),builds.end(),[](auto& b){return b.type==ObjectData::code("hars") && b.enabled;}),"Higher tier did not satisfy previous tier dependency");
        auto repaired=spawn("hhou",0,originX+2048,originY+768);auto repairState=session.units().at(repaired.bits);vm.invoke("SetWidgetLife",std::array{repaired,vm.real(real(number(repairState->maxLife)-100))});position(peasant,number(repairState->x)+session.buildingSize(repairState->type)[0]/2+24,number(repairState->y));check(session.repair(peasant.bits,repaired.bits),"Manual repair rejected");int beforeRepair=session.config().players[0].states.at(1);session.advance(12);check(number(repairState->life)==number(repairState->maxLife) && session.config().players[0].states.at(1)<beforeRepair,"Repair did not restore live HP and spend source repair cost");session.stopUnit(peasant.bits);vm.invoke("SetWidgetLife",std::array{repaired,vm.real(real(number(repairState->maxLife)-25))});check(session.repairAutocast(peasant.bits,true),"Repair autocast rejected");session.advance(1);check(number(repairState->life)>number(repairState->maxLife)-25,"Autocast flag did not reach repair consumer");session.repairAutocast(peasant.bits,false);session.stopUnit(peasant.bits);
        auto worker=session.units().at(peasant.bits);auto bridge=vm.invoke("CreateDeadDestructable",std::array{code("YT00"),vm.real(real(number(worker->x)+96)),vm.real(worker->y),vm.real(real(0)),vm.real(real(1)),vm.integer(0)});auto bridgeState=session.destructables().at(bridge.bits);auto beforeRevision=bridgeState->lifeRevision;int bridgeGold=session.config().players[0].states.at(1),bridgeLumber=session.config().players[0].states.at(2);check(session.targetOrder(peasant.bits,bridge.bits,852024),"Destroyed bridge repair command rejected");session.advance(8);check(bridgeState->life>0 && bridgeState->life<bridgeState->maxLife && bridgeState->lifeRevision==beforeRevision+1 && bridgeState->animation=="Stand", "Bridge repair failed to restore the live lifecycle");check(session.config().players[0].states.at(1)<bridgeGold && session.config().players[0].states.at(2)<bridgeLumber,"Bridge repair did not consume source resources");session.stopUnit(peasant.bits);
        auto assisted=place(peasant,"hhou");auto site=session.units().at(assisted.bits);auto helper=spawn("hpea",0,number(site->x)+session.buildingSize(site->type)[0]/2+24,number(site->y));check(session.repair(helper.bits,assisted.bits),"Human assisting worker was rejected");double progress=site->construction->elapsed;session.advance(1);check(site->construction->elapsed-progress>1 && session.units().at(helper.bits)->workingOn==assisted.bits,"Human power build did not increase real progress");session.cancelConstruction(assisted.bits);auto necropolis=spawn("unpl",0,originX+4096,originY+2048);auto undead=session.units().at(necropolis.bits);WorldPoint blightPoint{undead->x,undead->y};session.world()->blight(blightPoint,128,false);session.advance(1.5);check(session.world()->blighted(blightPoint),"Source blight growth did not reach shared terrain");
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS construction consumers: source placement/menu, lifecycle/events, worker methods, food/footprint, shared mines, upgrades, repair and blight\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
